INSERT OR IGNORE INTO records(id,country,system,data,version,updated_at) SELECT 'GBR-laser','GBR','laser','{"id":"GBR-laser","country":"GBR","system":"laser","batches":[],"signals":[{"year":2025,"text":"MBDA UK와 DragonFire 3.16억 파운드 계약, 2027년부터 Type 45 구축함 탑재 예정","src":["gbr_dragonfire"]}],"projects":[{"id":"GBR-dragonfire-mdc","buyer":"GBR","supplier":"MBDA UK","stage":"contract","text":"DragonFire 최소 배치 능력 개발·통합 계약(29개월), 2027년 첫 함정 통합 목표","src":["gbr_dragonfire"]}],"src":["gbr_dragonfire"]}',1,strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE EXISTS (SELECT 1 FROM countries WHERE id='GBR') AND EXISTS (SELECT 1 FROM systems WHERE id='laser') AND NOT EXISTS (SELECT 1 FROM records WHERE country='GBR' AND system='laser');
